package com.jaims.pdfpro;

import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.graphics.pdf.*;import android.net.Uri;import android.print.*;import android.view.*;import android.widget.*;import java.io.*;

public class MainActivity extends Activity {
  LinearLayout root;ImageView preview;EditText overlay;Uri source;byte[] result;int current=0,count=0;static final int OPEN=1,SAVE=2;
  @Override public void onCreate(Bundle b){super.onCreate(b);ScrollView sc=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(18,18,18,18);root.setBackgroundColor(Color.rgb(244,247,252));sc.addView(root);setContentView(sc);TextView h=new TextView(this);h.setText("JAIMS PDF Pro | Android Preview");h.setTextSize(23);h.setTextColor(Color.rgb(17,40,75));root.addView(h);button("Buka PDF",()->open());preview=new ImageView(this);preview.setAdjustViewBounds(true);preview.setMinimumHeight(260);root.addView(preview);button("Halaman sebelumnya",()->page(-1));button("Halaman seterusnya",()->page(1));overlay=new EditText(this);overlay.setHint("Teks tambahan pada setiap halaman");root.addView(overlay);button("Jana PDF dengan teks",()->export());button("Simpan PDF",()->save());button("Print",()->print());TextView note=new TextView(this);note.setText("Versi asas Android: baca PDF, tambah teks dan cetak. Edit teks asal, Signature Library dan OCR belum tersedia.");root.addView(note);}
  void button(String s,Runnable r){Button b=new Button(this);b.setText(s);root.addView(b);b.setOnClickListener(v->r.run());}
  void open(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("application/pdf");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,OPEN);}
  @Override protected void onActivityResult(int req,int code,Intent d){super.onActivityResult(req,code,d);if(code!=RESULT_OK||d==null)return;try{if(req==OPEN){source=d.getData();getContentResolver().takePersistableUriPermission(source,Intent.FLAG_GRANT_READ_URI_PERMISSION);current=0;showPage();}else if(req==SAVE&&result!=null){try(OutputStream o=getContentResolver().openOutputStream(d.getData())){o.write(result);}toast("Disimpan");}}catch(Exception e){toast(e.toString());}}
  void showPage(){if(source==null)return;try(android.os.ParcelFileDescriptor fd=getContentResolver().openFileDescriptor(source,"r");PdfRenderer renderer=new PdfRenderer(fd)){count=renderer.getPageCount();try(PdfRenderer.Page p=renderer.openPage(current)){int w=Math.max(1,p.getWidth()*2),h=Math.max(1,p.getHeight()*2);Bitmap b=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);b.eraseColor(Color.WHITE);p.render(b,null,null,PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);preview.setImageBitmap(b);}}catch(Exception e){toast(e.toString());}}
  void page(int delta){if(source!=null){current=Math.max(0,Math.min(count-1,current+delta));showPage();}}
  void export(){if(source==null){toast("Buka PDF dahulu");return;}try(android.os.ParcelFileDescriptor fd=getContentResolver().openFileDescriptor(source,"r");PdfRenderer renderer=new PdfRenderer(fd)){PdfDocument doc=new PdfDocument();for(int i=0;i<renderer.getPageCount();i++){try(PdfRenderer.Page rp=renderer.openPage(i)){int w=rp.getWidth(),h=rp.getHeight();Bitmap b=Bitmap.createBitmap(w*2,h*2,Bitmap.Config.ARGB_8888);b.eraseColor(Color.WHITE);rp.render(b,null,null,PdfRenderer.Page.RENDER_MODE_FOR_PRINT);PdfDocument.Page pp=doc.startPage(new PdfDocument.PageInfo.Builder(w,h,i+1).create());Canvas c=pp.getCanvas();c.drawBitmap(b,null,new Rect(0,0,w,h),new Paint(3));String s=overlay.getText().toString();if(!s.isEmpty()){Paint t=new Paint(3);t.setColor(Color.BLACK);t.setTextSize(14);c.drawText(s,35,h-45,t);}doc.finishPage(pp);b.recycle();}}ByteArrayOutputStream o=new ByteArrayOutputStream();doc.writeTo(o);result=o.toByteArray();doc.close();toast("PDF dijana. Nota: halaman diraster semula.");}catch(Exception e){toast(e.toString());}}
  void save(){if(result==null){toast("Jana PDF dahulu");return;}Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/pdf");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_TITLE,"JAIMS_PDF_Pro.pdf");startActivityForResult(i,SAVE);}
  void print(){if(result==null){toast("Jana PDF dahulu");return;}PrintManager pm=(PrintManager)getSystemService(PRINT_SERVICE);pm.print("JAIMS PDF Pro",new PrintDocumentAdapter(){@Override public void onLayout(PrintAttributes o,PrintAttributes n,CancellationSignal cs,LayoutResultCallback cb,Bundle extras){cb.onLayoutFinished(new PrintDocumentInfo.Builder("JAIMS_Pro.pdf").setContentType(PrintDocumentInfo.CONTENT_TYPE_DOCUMENT).setPageCount(count).build(),true);}@Override public void onWrite(PageRange[] pages,android.os.ParcelFileDescriptor fd,CancellationSignal cs,WriteResultCallback cb){try(FileOutputStream out=new FileOutputStream(fd.getFileDescriptor())){out.write(result);cb.onWriteFinished(new PageRange[]{PageRange.ALL_PAGES});}catch(Exception e){cb.onWriteFailed(e.toString());}}},null);}
  void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
}
